// 5. 16タイプ（MBTI）性格・コミュニケーション相性判定
export function getMbtiCognitiveDynamics(myMbti, oppMbti, myNick, oppNick) {
    const myNorm = (myMbti || 'ENFP').toUpperCase();
    const oppNorm = (oppMbti || 'INFJ').toUpperCase();
    const myT = myNorm.includes('T');
    const oppT = oppNorm.includes('T');
    let tfText = '';
    if (!myT && oppT) {
        tfText = `論理的に物事を考えるタイプの${san(oppNick)}に対し、気持ちや共感を大切にするタイプの${san(myNick)}。${san(oppNick)}は悪気なくアドバイスや解決策を言いがちですが、${san(myNick)}が本当に求めているのは「共感して話を聞いてくれること」です。この考え方の違いをあらかじめ知っておくだけで、些細なすれ違いやモヤモヤをスッキリ解消できます。`;
    }
    else if (myT && !oppT) {
        tfText = `気持ちや共感を大切にするタイプの${san(oppNick)}に対し、冷静で論理的なタイプの${san(myNick)}。${san(oppNick)}は解決策よりも「気持ちを分かってほしい」と思っています。アドバイスする前にまず「それは大変だったね」「わかるよ」と共感してあげるだけで、相手の心は一気にあなたに開いていきます。`;
    }
    else if (myT && oppT) {
        tfText = `お互いに冷静で論理的な考え方ができるスマートな二人。感情的にならずサバサバと話し合える相性ですが、お互いに素直な弱音を吐きづらい面もあります。照れずに「嬉しい」「寂しい」などの素直な気持ちを言葉で伝えることが、もっと仲良くなる秘密です。`;
    }
    else {
        tfText = `お互いに相手の気持ちを優しく察し合える、思いやりいっぱいの二人。相手の痛みに寄り添える一方で、気を遣いすぎて言いたいことを我慢してしまいがちです。我慢を溜め込まずに、小さなお願いや本音を可愛く伝えることが長続きのコツです。`;
    }
    const myJ = myNorm.includes('J');
    const oppJ = oppNorm.includes('J');
    let jpText = '';
    if (myJ !== oppJ) {
        jpText = `また、きっちり計画を立てたいタイプと、その場の直感やノリを大切にしたいタイプで、デートの予定決めや連絡のペースに少し違いが出やすいですが、お互いの足りないところを補い合える、いいバランスです。`;
    }
    else if (myJ && oppJ) {
        jpText = `また、二人ともしっかり計画を立てて行動するタイプなので、約束や将来の計画を安心して進められる抜群の信頼関係があります。`;
    }
    else {
        jpText = `また、二人とも自由で楽しいことが大好きなタイプなので、思いつきのドライブや新しいスポット巡りなど、二人だけの楽しい思い出をどんどん作っていける最高のノリがあります。`;
    }
    let mbtiPairType = '補い合いペア';
    if (myNorm === oppNorm)
        mbtiPairType = 'そっくりペア';
    else if (myT === oppT && myJ === oppJ)
        mbtiPairType = '価値観が近いペア';
    else if (myT !== oppT && myJ !== oppJ)
        mbtiPairType = '正反対ペア';
    return {
        tfText,
        jpText,
        mbtiPairType,
        summary: `${tfText}\n\n${jpText}`
    };
}
